uint32_t crc = init_crc;
const uint8_t* buf = reinterpret_cast<const uint8_t*>(data);
const uint8_t* end = buf + n;

// Process individual bytes until we reach an 8-byte aligned boundary
while (buf < end && (reinterpret_cast<uintptr_t>(buf) & 7) != 0) {
    crc = kByteExtensionTable[(crc ^ *buf) & 0xff] ^ (crc >> 8);
    buf++;
}

// Process 8 bytes at a time using stride tables
while (buf + 8 <= end) {
    crc ^= *reinterpret_cast<const uint32_t*>(buf);
    uint32_t part0 = *reinterpret_cast<const uint32_t*>(buf + 4);
    crc = kStrideExtensionTable1[(crc >> 24) & 0xff] ^
          kStrideExtensionTable0[(part0 >> 24) & 0xff] ^
          kStrideExtensionTable1[(part0 >> 16) & 0xff] ^
          kStrideExtensionTable0[(part0 >> 8) & 0xff] ^
          kStrideExtensionTable1[part0 & 0xff] ^
          kStrideExtensionTable0[(crc >> 16) & 0xff] ^
          kStrideExtensionTable1[(crc >> 8) & 0xff] ^
          kStrideExtensionTable0[crc & 0xff];
    buf += 8;
}

// Process remaining bytes
while (buf < end) {
    crc = kByteExtensionTable[(crc ^ *buf) & 0xff] ^ (crc >> 8);
    buf++;
}

return crc;

